<?php defined( 'ABSPATH' ) || exit; get_header(); while ( have_posts() ) : the_post(); $id = get_the_ID(); $cafe_id = (int) get_post_meta( $id, '_matin_cafe_id', true ); $starts = (string) get_post_meta( $id, '_matin_starts_at', true ); $ends = (string) get_post_meta( $id, '_matin_ends_at', true ); $bookable_capacity = max( 0, (int) get_post_meta( $id, '_matin_bookable_capacity', true ) ); $table_count = max( 0, (int) get_post_meta( $id, '_matin_table_count', true ) ); $seats_per_table = max( 1, (int) get_post_meta( $id, '_matin_seats_per_table', true ) ?: 4 ); $legacy_capacity = max( 0, (int) get_post_meta( $id, '_matin_capacity', true ) ); $capacity = $bookable_capacity > 0 ? $bookable_capacity : ( $table_count > 0 ? $table_count * $seats_per_table : $legacy_capacity ); $reserved = get_posts( [ 'post_type' => 'matin_reservation', 'post_status' => 'any', 'numberposts' => -1, 'fields' => 'ids', 'meta_query' => [ [ 'key' => '_matin_event_id', 'value' => $id ], [ 'key' => '_matin_status', 'value' => [ 'pending', 'confirmed' ], 'compare' => 'IN' ] ] ] ); $taken = 0; foreach ( $reserved as $rid ) { $taken += (int) get_post_meta( $rid, '_matin_guests', true ); } ?>
<main id="main" class="matin-detail" dir="rtl"><a class="matin-back" href="<?php echo esc_url( get_post_type_archive_link( 'matin_event' ) ); ?>">← همه رویدادها</a><article class="matin-detail-panel"><?php if ( has_post_thumbnail() ) : ?><div class="matin-detail-image"><?php the_post_thumbnail( 'large' ); ?></div><?php endif; ?><p class="matin-kicker">MATIN AI · EVENT</p><h1><?php the_title(); ?></h1><div class="matin-detail-copy"><?php the_content(); ?></div><dl class="matin-detail-facts"><dt>کافه</dt><dd><a href="<?php echo esc_url( get_permalink( $cafe_id ) ); ?>"><?php echo esc_html( get_the_title( $cafe_id ) ?: 'کافه نامشخص' ); ?></a></dd><dt>شروع</dt><dd><?php echo esc_html( Matin_AI_Operations::format_event_time( $id ) ?: 'ثبت نشده' ); ?></dd><?php if ( $ends ) : ?><dt>پایان</dt><dd><?php echo esc_html( str_replace( 'T', ' ', $ends ) ); ?></dd><?php endif; ?><dt>ظرفیت باقی‌مانده (تقریبی)</dt><dd><?php echo esc_html( (string) max( 0, $capacity - $taken ) ); ?> نفر</dd><dt>قیمت ورودی</dt><dd><?php echo esc_html( number_format_i18n( (int) get_post_meta( $id, '_matin_event_price', true ) ) ); ?> لیر</dd><?php if ( get_post_meta( $id, '_matin_performer', true ) ) : ?><dt>هنرمند</dt><dd><?php echo esc_html( (string) get_post_meta( $id, '_matin_performer', true ) ); ?></dd><?php endif; ?><?php if ( get_post_meta( $id, '_matin_match_teams', true ) ) : ?><dt>مسابقه</dt><dd><?php echo esc_html( (string) get_post_meta( $id, '_matin_match_teams', true ) ); ?></dd><?php endif; ?><?php if ( get_post_meta( $id, '_matin_competition', true ) ) : ?><dt>لیگ / رقابت</dt><dd><?php echo esc_html( (string) get_post_meta( $id, '_matin_competition', true ) ); ?></dd><?php endif; ?><?php if ( get_post_meta( $id, '_matin_ticket_instructions', true ) ) : ?><dt>اطلاعات تکمیلی بلیت</dt><dd><?php echo nl2br( esc_html( (string) get_post_meta( $id, '_matin_ticket_instructions', true ) ) ); ?></dd><?php endif; ?></dl><a class="matin-catalog-cta" href="<?php echo esc_url( add_query_arg( 'event', $id, home_url( '/' ) ) ); ?>">برای درخواست رزرو با دستیار ماتین گفتگو کنید <span aria-hidden="true">←</span></a><p class="matin-detail-note">رزرو با ثبت موفق، تأیید و با رسید همراه است. ظرفیت نمایش‌داده‌شده بر اساس رزروهای ثبت‌شده محاسبه می‌شود.</p></article></main><?php endwhile; get_footer(); ?>
